window.EW=window.EW||{pages:{}};window.EW.pages["wiki-bestiaire--rang-aaaa"]={"html":"<div class=\"tbl-wrap\"><table class=\"doc-table\"><thead><tr><th scope=\"col\">Rang<\/th><th scope=\"col\">Description<\/th><\/tr><\/thead><tbody><tr><td>Nyxaris<\/td><td>Panthère noire marquée de motifs rouges lumineux qui s'illuminent lorsqu'ils sont chargés de Flux.<\/td><\/tr><tr><td>Phénix<\/td><td>Oiseau magique extrêmement rare au plumage écarlate et or, dont le chant peut redonner courage.<\/td><\/tr><tr><td>Dracoryx<\/td><td>Serpent ailé très rare aux écailles nacrées aux reflets argentés et bleutés, et aux yeux dorés.<\/td><\/tr><tr><td>Noctilure<\/td><td>Créature redoutée à l'apparence fragile, à la peau pâle et translucide et aux grands yeux sombres.<\/td><\/tr><tr><td>L’Abyssalith<\/td><td>Golem de roches noires incrusté de cristaux luminescents, forgé pour garder des secrets enfouis sous terre.<\/td><\/tr><tr><td>La Licorne<\/td><td>Créature légendaire au pelage blanc immaculé et à la corne d'or translucide, bien plus puissante qu'elle n'y paraît.<\/td><\/tr><tr><td>Mycollin Épineux<\/td><td>Mutation extrêmement rare et dangereuse du Mycollin, elle ressemble plus à un squelette qu'un champignon.<\/td><\/tr><tr><td><a href=\"#/p/wiki-bestiaire--rang-aaaa--matriarche\">Matriarche d'Ether<\/a><\/td><td>Grande Araignée d'Ether, Une des nombreuses maîtresse de nid qui contrôle Brûlebrume et rejeton de la Tisseuse Primordiale<\/td><\/tr><\/tbody><\/table><\/div>","toc":[]};
